  "COUNTRY" VARCHAR2(100),
  "INDUSTRY" VARCHAR2(150),
  "PRIMARY_CONTACT_NAME" VARCHAR2(200),
  "PRIMARY_CONTACT_EMAIL" VARCHAR2(200),
  "PRIMARY_CONTACT_PHONE" VARCHAR2(50),
  "CRITICALITY" VARCHAR2(20),
  "RISK_TIER" VARCHAR2(20),
  "INHERENT_RISK_SCORE" NUMBER(5,2),
  "RESIDUAL_RISK_SCORE" NUMBER(5,2),
  "ONBOARDED_DATE" DATE,
  "OFFBOARDED_DATE" DATE,
  "STATUS" VARCHAR2(30) DEFAULT 'ACTIVE',
