  "CREATED_BY" VARCHAR2(255),
  "CREATED_ON" DATE DEFAULT SYSDATE,
  "UPDATED_BY" VARCHAR2(255),
  "UPDATED_ON" DATE,
  "RISK_RATING" VARCHAR2(50) GENERATED ALWAYS AS (CAST("CRITICALITY" AS VARCHAR2(50))) VIRTUAL,
