  PRIMARY KEY ("UUID") ENABLE,
  UNIQUE ("VENDOR_CODE") ENABLE
)
ANNOTATIONS("DESCRIPTION" 'Vendor master. RISK_RATING / RISK_TIER / CRITICALITY are the vendor risk fields; INHERENT_RISK_SCORE and RESIDUAL_RISK_SCORE are numeric. "Third party" and "supplier" mean vendor.');

