CREATE TABLE "PER_TRN_COMPLIANCE_GAP" (
  "UUID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "OBLIGATION_UUID" NUMBER NOT NULL ENABLE,
  "ASSESSMENT_CYCLE_UUID" NUMBER,
  "GAP_TITLE" VARCHAR2(300) NOT NULL ENABLE,
  "GAP_DESCRIPTION" CLOB,
  "CURRENT_STATE" CLOB,
  "TARGET_STATE" CLOB,
  "GAP_SEVERITY" VARCHAR2(20),
  "GAP_OWNER_UUID" NUMBER,
  "TARGET_CLOSURE_DATE" DATE,
  "ACTUAL_CLOSURE_DATE" DATE,
  "COMPLETION_PCT" NUMBER(3,0) DEFAULT 0,
  "STATUS" VARCHAR2(30) DEFAULT 'OPEN',
  "APPROVAL_STATUS" VARCHAR2(30) DEFAULT 'DRAFT' NOT NULL ENABLE,
  "APPROVER_COMMENTS" VARCHAR2(2000),
  "APPROVED_BY" VARCHAR2(255),
  "APPROVED_ON" DATE,
  "CREATED_BY" VARCHAR2(255),
  "CREATED_ON" DATE DEFAULT SYSDATE,
  "UPDATED_BY" VARCHAR2(255),
  "UPDATED_ON" DATE,
  PRIMARY KEY ("UUID") ENABLE
)
ANNOTATIONS("DESCRIPTION" 'Compliance gaps via OBLIGATION_UUID = PER_MST_COMPLIANCE_OBLIGATION.UUID. This table has NO framework name column directly -- grouping by OBLIGATION_UUID alone shows a meaningless raw ID to the user. For "which framework has the most gaps" or any framework-level gap question, use PER_VW_COMPLIANCE_POSTURE instead, which already resolves FRAMEWORK_NAME and pre-counts OPEN_GAPS/OVERDUE_GAPS per obligation.');

CREATE TABLE "PER_TRN_COMPLIANCE_MAPPING" (
  "UUID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "OBLIGATION_UUID" NUMBER NOT NULL ENABLE,
