  "RISK_IMPACT_CATEGORY_UUID" NUMBER,
  "RISK_IMPACT_SUB_CATEGORY_UUID" NUMBER,
  "RISK_INHERENT_IMPACT_LEVEL" NUMBER,
  "RISK_RESIDUAL_IMPACT_LEVEL" NUMBER,
  CONSTRAINT "PER_TRN_IMPACT_CATEGORY_PK" PRIMARY KEY ("UUID") ENABLE
);

CREATE TABLE "PER_TRN_INCIDENT" (
  "UUID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "INCIDENT_REFERENCE" VARCHAR2(50) NOT NULL ENABLE,
  "INCIDENT_TITLE" VARCHAR2(300) NOT NULL ENABLE,
  "INCIDENT_DESCRIPTION" CLOB,
  "INCIDENT_TYPE_UUID" NUMBER NOT NULL ENABLE,
  "SEVERITY_UUID" NUMBER NOT NULL ENABLE,
  "STATUS_UUID" NUMBER NOT NULL ENABLE,
  "RISK_UUID" NUMBER,
  "IDENTIFY_RISK_UUID" NUMBER,
  "ORG_HIERARCHY_UUID" NUMBER,
  "REPORTED_BY_UUID" NUMBER,
  "INCIDENT_OWNER_UUID" NUMBER,
  "REPORTED_ON" DATE DEFAULT SYSDATE NOT NULL ENABLE,
  "OCCURRED_ON" DATE,
  "DETECTED_ON" DATE,
  "TARGET_RESOLUTION_ON" DATE,
  "ACTUAL_RESOLUTION_ON" DATE,
  "ROOT_CAUSE_SUMMARY" CLOB,
  "CORRECTIVE_ACTION_SUMMARY" CLOB,
  "FINANCIAL_IMPACT" NUMBER(18,2),
  "CURRENCY_TYPE_UUID" NUMBER,
  "IS_SLA_BREACHED" VARCHAR2(1) DEFAULT 'N',
  "APPROVAL_STATUS" VARCHAR2(30) DEFAULT 'DRAFT' NOT NULL ENABLE,
  "APPROVER_COMMENTS" VARCHAR2(2000),
  "APPROVED_BY" VARCHAR2(255),
  "APPROVED_ON" DATE,
  "CREATED_BY" VARCHAR2(255),
  "CREATED_ON" DATE DEFAULT SYSDATE,
  "UPDATED_BY" VARCHAR2(255),
  "UPDATED_ON" DATE,
  PRIMARY KEY ("UUID") ENABLE,
  UNIQUE ("INCIDENT_REFERENCE") ENABLE
)
ANNOTATIONS("DESCRIPTION" 'Incident log. WARNING: there is NO plain INCIDENT_TYPE text column on this table -- the type NAME only exists via JOIN: INCIDENT_TYPE_UUID = PER_MST_INCIDENT_TYPE.UUID, giving TYPE_NAME. Same pattern for SEVERITY_UUID -> PER_MST_INCIDENT_SEVERITY.SEVERITY_NAME and STATUS_UUID -> PER_MST_INCIDENT_STATUS.STATUS_NAME. FINANCIAL_IMPACT holds monetary loss. For ANY question combining incident type/severity/status with cost, count, or other detail, use PER_VW_INCIDENT_SUMMARY instead -- it already resolves all three names and computes RESOLUTION_DAYS and IS_OVERDUE.');

