-- ############################################################################
-- STEP 04: App alignment
-- ############################################################################
PROMPT ===== Step 04: App alignment
-- =============================================================================
-- 04  Make the exported schema match what the web app writes
--
-- Run after 03_foreign_keys.sql and before the migrations (db/migrations V1–V4).
-- Each change is skipped if it is already in place, so this file is safe to re-run.
--
-- 1. PER_TRN_RISK_MONITORING gets IDENTIFY_RISK_UUID and ASSESSMENT_REFERENCE_NUMBER_UUID:
--    the app links an action to its risk with them (V2 then indexes and keys the first one).
-- 2. PER_TRN_RISK_MONITORING.ROOT_CAUSE becomes text: the action-plan form saves a sentence,
--    which a NUMBER column rejects.
-- 3. PER_TRN_INHERENT_RISK_ASSESSMENT gets CREATED_ON / CREATED_BY, so the assessment history
--    shows when and by whom each assessment was saved.
-- 4. The risk register's approval-status check also allows IN_REVIEW and PENDING, the
--    in-between states the approval workflow uses.
-- =============================================================================
SET SERVEROUTPUT ON
DECLARE
  n NUMBER;
  PROCEDURE add_column(p_table VARCHAR2, p_column VARCHAR2, p_definition VARCHAR2) IS
  BEGIN
    SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = p_table AND column_name = p_column;
    IF n = 0 THEN
      EXECUTE IMMEDIATE 'ALTER TABLE ' || p_table || ' ADD (' || p_column || ' ' || p_definition || ')';
      DBMS_OUTPUT.PUT_LINE('Added ' || p_table || '.' || p_column);
    END IF;
  END;
BEGIN
  -- 1
  add_column('PER_TRN_RISK_MONITORING', 'IDENTIFY_RISK_UUID', 'NUMBER');
  add_column('PER_TRN_RISK_MONITORING', 'ASSESSMENT_REFERENCE_NUMBER_UUID', 'NUMBER');

  -- 2 (only while the column is still a number and empty; the table is empty on a fresh install)
  SELECT COUNT(*) INTO n FROM user_tab_columns
   WHERE table_name = 'PER_TRN_RISK_MONITORING' AND column_name = 'ROOT_CAUSE' AND data_type = 'NUMBER';
  IF n > 0 THEN
    EXECUTE IMMEDIATE 'SELECT COUNT(*) FROM PER_TRN_RISK_MONITORING WHERE ROOT_CAUSE IS NOT NULL' INTO n;
    IF n = 0 THEN
      EXECUTE IMMEDIATE 'ALTER TABLE PER_TRN_RISK_MONITORING MODIFY (ROOT_CAUSE VARCHAR2(2000 CHAR))';
      DBMS_OUTPUT.PUT_LINE('PER_TRN_RISK_MONITORING.ROOT_CAUSE is now text');
    ELSE
      DBMS_OUTPUT.PUT_LINE('WARNING: PER_TRN_RISK_MONITORING.ROOT_CAUSE has data, left as a number');
    END IF;
  END IF;

  -- 3
  add_column('PER_TRN_INHERENT_RISK_ASSESSMENT', 'CREATED_ON', 'DATE DEFAULT SYSDATE');
  add_column('PER_TRN_INHERENT_RISK_ASSESSMENT', 'CREATED_BY', 'VARCHAR2(255 CHAR)');

  -- 4
  SELECT COUNT(*) INTO n FROM user_constraints WHERE table_name = 'PER_TRN_IDENTIFY_RISK' AND constraint_name = 'CK_IDR_APPR_STATUS';
  IF n > 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE PER_TRN_IDENTIFY_RISK DROP CONSTRAINT CK_IDR_APPR_STATUS';
  END IF;
  EXECUTE IMMEDIATE q'[ALTER TABLE PER_TRN_IDENTIFY_RISK ADD CONSTRAINT CK_IDR_APPR_STATUS
    CHECK (APPROVAL_STATUS IS NULL OR APPROVAL_STATUS IN ('DRAFT','SUBMITTED','IN_REVIEW','PENDING','APPROVED','REJECTED'))]';
  DBMS_OUTPUT.PUT_LINE('Approval statuses: DRAFT, SUBMITTED, IN_REVIEW, PENDING, APPROVED, REJECTED');
END;
/

-- ############################################################################
-- STEP 05a: Migration V1
-- ############################################################################
PROMPT ===== Step 05a: Migration V1
-- =============================================================================
-- V1  Pericope DDL helpers
-- Small idempotent helpers used by later migrations, so each migration can be
-- re-run safely on a schema that already has some of its objects.
-- Oracle Autonomous Database 19c+ (ORDS installed). Run as the schema owner.
--
-- Every message (and especially every WARNING) is also written to the table
-- PERICOPE_MIGRATION_LOG, because tools such as Flyway don't show DBMS_OUTPUT:
--   SELECT * FROM pericope_migration_log WHERE log_level = 'WARNING' ORDER BY logged_on;
-- =============================================================================

DECLARE
  n NUMBER;
BEGIN
  SELECT COUNT(*) INTO n FROM user_tables WHERE table_name = 'PERICOPE_MIGRATION_LOG';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'CREATE TABLE PERICOPE_MIGRATION_LOG (
      LOG_ID    NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
      LOGGED_ON TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
      LOG_LEVEL VARCHAR2(10) NOT NULL,
      MESSAGE   VARCHAR2(4000))';
  END IF;
END;
/

CREATE OR REPLACE PACKAGE pericope_ddl AUTHID CURRENT_USER AS
  -- Create a table from its column list, e.g. create_table('T', 'ID NUMBER PRIMARY KEY, NAME VARCHAR2(10)')
  PROCEDURE create_table(p_table VARCHAR2, p_columns CLOB);
  PROCEDURE add_column(p_table VARCHAR2, p_column VARCHAR2, p_definition VARCHAR2);
  PROCEDURE create_index(p_index VARCHAR2, p_table VARCHAR2, p_columns VARCHAR2);
  -- p_definition is everything after "ADD CONSTRAINT <name>", e.g. 'CHECK (x > 0)'
  PROCEDURE add_constraint(p_table VARCHAR2, p_constraint VARCHAR2, p_definition VARCHAR2);
  -- Foreign key, fully validated. If existing rows point at missing parents the key is NOT added
  -- (a WARNING says how many rows; fix them with db/scripts/find_orphans.sql and re-run).
  -- p_on_delete: NULL (restrict), 'CASCADE' or 'SET NULL'.
  PROCEDURE add_fk(p_table VARCHAR2, p_constraint VARCHAR2, p_column VARCHAR2,
                   p_ref_table VARCHAR2, p_ref_column VARCHAR2 DEFAULT 'UUID', p_on_delete VARCHAR2 DEFAULT NULL);
  PROCEDURE log_msg(p_level VARCHAR2, p_message VARCHAR2);
  -- Expose a table/view through ORDS AutoREST with authentication required.
  PROCEDURE enable_rest(p_object VARCHAR2, p_type VARCHAR2 DEFAULT 'TABLE');
  FUNCTION table_exists(p_table VARCHAR2) RETURN BOOLEAN;
END pericope_ddl;
/

CREATE OR REPLACE PACKAGE BODY pericope_ddl AS
  PROCEDURE log_msg(p_level VARCHAR2, p_message VARCHAR2) IS
    PRAGMA AUTONOMOUS_TRANSACTION;
  BEGIN
    DBMS_OUTPUT.PUT_LINE(p_level || ': ' || p_message);
    EXECUTE IMMEDIATE 'INSERT INTO PERICOPE_MIGRATION_LOG (LOG_LEVEL, MESSAGE) VALUES (:1, :2)'
      USING p_level, SUBSTR(p_message, 1, 4000);
    COMMIT;
  END;

  FUNCTION table_exists(p_table VARCHAR2) RETURN BOOLEAN IS
    n NUMBER;
  BEGIN
    SELECT COUNT(*) INTO n FROM user_objects
     WHERE object_name = UPPER(p_table) AND object_type IN ('TABLE', 'VIEW');
    RETURN n > 0;
  END;

  PROCEDURE create_table(p_table VARCHAR2, p_columns CLOB) IS
  BEGIN
    IF table_exists(p_table) THEN
      log_msg('INFO', 'table ' || p_table || ' already exists');
      RETURN;
    END IF;
    EXECUTE IMMEDIATE 'CREATE TABLE ' || p_table || ' (' || p_columns || ')';
    log_msg('INFO', 'created table ' || p_table);
  END;

  PROCEDURE add_column(p_table VARCHAR2, p_column VARCHAR2, p_definition VARCHAR2) IS
    n NUMBER;
  BEGIN
    IF NOT table_exists(p_table) THEN
      log_msg('INFO', 'skip column ' || p_table || '.' || p_column || ': table missing');
      RETURN;
    END IF;
    SELECT COUNT(*) INTO n FROM user_tab_columns
     WHERE table_name = UPPER(p_table) AND column_name = UPPER(p_column);
    IF n = 0 THEN
      EXECUTE IMMEDIATE 'ALTER TABLE ' || p_table || ' ADD (' || p_column || ' ' || p_definition || ')';
      log_msg('INFO', 'added column ' || p_table || '.' || p_column);
    END IF;
  END;

  PROCEDURE create_index(p_index VARCHAR2, p_table VARCHAR2, p_columns VARCHAR2) IS
    n NUMBER;
    already_indexed EXCEPTION;
    PRAGMA EXCEPTION_INIT(already_indexed, -1408);
    no_column EXCEPTION;
    PRAGMA EXCEPTION_INIT(no_column, -904);
  BEGIN
    IF NOT table_exists(p_table) THEN
      log_msg('INFO', 'skip index ' || p_index || ': table missing');
      RETURN;
    END IF;
    SELECT COUNT(*) INTO n FROM user_indexes WHERE index_name = UPPER(p_index);
    IF n = 0 THEN
      EXECUTE IMMEDIATE 'CREATE INDEX ' || p_index || ' ON ' || p_table || ' (' || p_columns || ')';
      log_msg('INFO', 'created index ' || p_index);
    END IF;
  EXCEPTION
    WHEN already_indexed THEN log_msg('INFO', 'skip index ' || p_index || ': columns already indexed');
    WHEN no_column THEN log_msg('INFO', 'skip index ' || p_index || ': column missing');
  END;

  PROCEDURE add_constraint(p_table VARCHAR2, p_constraint VARCHAR2, p_definition VARCHAR2) IS
    n NUMBER;
  BEGIN
    IF NOT table_exists(p_table) THEN
      log_msg('INFO', 'skip constraint ' || p_constraint || ': table missing');
      RETURN;
    END IF;
    SELECT COUNT(*) INTO n FROM user_constraints WHERE constraint_name = UPPER(p_constraint);
    IF n = 0 THEN
      EXECUTE IMMEDIATE 'ALTER TABLE ' || p_table || ' ADD CONSTRAINT ' || p_constraint || ' ' || p_definition;
      log_msg('INFO', 'added constraint ' || p_constraint);
    END IF;
  EXCEPTION
    -- A constraint that can't be added (e.g. the referenced key is not unique) must not stop the
    -- migration; it is reported so it can be fixed by hand.
    WHEN OTHERS THEN
      log_msg('WARNING', 'could not add ' || p_constraint || ' on ' || p_table || ': ' || SQLERRM);
  END;

  PROCEDURE add_fk(p_table VARCHAR2, p_constraint VARCHAR2, p_column VARCHAR2,
                   p_ref_table VARCHAR2, p_ref_column VARCHAR2 DEFAULT 'UUID', p_on_delete VARCHAR2 DEFAULT NULL) IS
    n       NUMBER;
    orphans NUMBER;
  BEGIN
    IF NOT table_exists(p_table) OR NOT table_exists(p_ref_table) THEN
      log_msg('INFO', 'skip ' || p_constraint || ': table missing');
      RETURN;
    END IF;
    SELECT COUNT(*) INTO n FROM user_constraints WHERE constraint_name = UPPER(p_constraint);
    IF n > 0 THEN
      RETURN;
    END IF;
    EXECUTE IMMEDIATE 'SELECT COUNT(*) FROM ' || p_table || ' c WHERE c.' || p_column || ' IS NOT NULL'
      || ' AND NOT EXISTS (SELECT 1 FROM ' || p_ref_table || ' p WHERE p.' || p_ref_column || ' = c.' || p_column || ')'
      INTO orphans;
    IF orphans > 0 THEN
      log_msg('WARNING', 'foreign key ' || p_constraint || ' not added: ' || orphans || ' row(s) of ' || p_table
        || ' reference a missing ' || p_ref_table || '. Fix them (db/scripts/find_orphans.sql) and re-run this migration.');
      RETURN;
    END IF;
    EXECUTE IMMEDIATE 'ALTER TABLE ' || p_table || ' ADD CONSTRAINT ' || p_constraint
      || ' FOREIGN KEY (' || p_column || ') REFERENCES ' || p_ref_table || ' (' || p_ref_column || ')'
      || CASE WHEN p_on_delete IS NOT NULL THEN ' ON DELETE ' || p_on_delete END;
    log_msg('INFO', 'added foreign key ' || p_constraint);
  EXCEPTION
    WHEN OTHERS THEN
      IF SQLCODE = -2275 THEN
        -- ORA-02275: the same key already exists under another name (e.g. from the original schema)
        log_msg('INFO', 'skip ' || p_constraint || ': ' || p_table || '.' || p_column || ' already has this foreign key');
      ELSE
        log_msg('WARNING', 'could not add ' || p_constraint || ' on ' || p_table || ': ' || SQLERRM);
      END IF;
  END;

  PROCEDURE enable_rest(p_object VARCHAR2, p_type VARCHAR2 DEFAULT 'TABLE') IS
  BEGIN
    EXECUTE IMMEDIATE q'[
      BEGIN
        ORDS.ENABLE_OBJECT(
          p_enabled        => TRUE,
          p_schema         => SYS_CONTEXT('USERENV', 'CURRENT_SCHEMA'),
          p_object         => :obj,
          p_object_type    => :typ,
          p_object_alias   => LOWER(:obj),
          p_auto_rest_auth => TRUE);
      END;]' USING UPPER(p_object), UPPER(p_type);  -- in a PL/SQL block a repeated placeholder binds once
    log_msg('INFO', 'REST-enabled (auth required) ' || p_object);
  EXCEPTION
    WHEN OTHERS THEN
      log_msg('WARNING', 'could not REST-enable ' || p_object || ': ' || SQLERRM);
  END;
END pericope_ddl;
/

-- ############################################################################
-- STEP 05b: Migration V2
-- ############################################################################
PROMPT ===== Step 05b: Migration V2
-- =============================================================================
-- V2  Risk scoring columns, foreign-key indexes and referential integrity
--
-- * Adds explicit 1–5 likelihood / impact ratings (inherent and residual) to the
--   risk register, so scores are stored instead of being guessed from the SLE.
-- * Indexes the columns used to join records.
-- * Adds fully validated foreign keys. Where existing rows already point at missing
--   parents the key is skipped with a WARNING in PERICOPE_MIGRATION_LOG (fix the rows with
--   db/scripts/find_orphans.sql, then re-run). Keys are never added "NOVALIDATE", because the
--   API updates whole rows and would then fail on every edit of such a legacy row.
-- * Children of a risk (applied controls, action plans, assessment records, KRI readings)
--   are deleted with their parent.
-- Safe to re-run.
-- =============================================================================

BEGIN
  -- Likelihood × impact ratings on the risk register
  pericope_ddl.add_column('PER_TRN_IDENTIFY_RISK', 'INHERENT_LIKELIHOOD', 'NUMBER(1)');
  pericope_ddl.add_column('PER_TRN_IDENTIFY_RISK', 'INHERENT_IMPACT',     'NUMBER(1)');
  pericope_ddl.add_column('PER_TRN_IDENTIFY_RISK', 'RESIDUAL_LIKELIHOOD', 'NUMBER(1)');
  pericope_ddl.add_column('PER_TRN_IDENTIFY_RISK', 'RESIDUAL_IMPACT',     'NUMBER(1)');
  pericope_ddl.add_constraint('PER_TRN_IDENTIFY_RISK', 'CHK_PIR_INH_L', 'CHECK (INHERENT_LIKELIHOOD BETWEEN 1 AND 5)');
  pericope_ddl.add_constraint('PER_TRN_IDENTIFY_RISK', 'CHK_PIR_INH_I', 'CHECK (INHERENT_IMPACT BETWEEN 1 AND 5)');
  pericope_ddl.add_constraint('PER_TRN_IDENTIFY_RISK', 'CHK_PIR_RES_L', 'CHECK (RESIDUAL_LIKELIHOOD BETWEEN 1 AND 5)');
  pericope_ddl.add_constraint('PER_TRN_IDENTIFY_RISK', 'CHK_PIR_RES_I', 'CHECK (RESIDUAL_IMPACT BETWEEN 1 AND 5)');
  pericope_ddl.add_constraint('PER_TRN_IDENTIFY_RISK', 'CHK_PIR_SLE',   'CHECK (INHERENT_SLE >= 0)');

  -- Monitoring progress is a percentage
  pericope_ddl.add_constraint('PER_TRN_RISK_MONITORING', 'CHK_PRM_PCT', 'CHECK (COMPLETION_PCT BETWEEN 0 AND 100)');

  -- KRI definitions: owner and which direction is bad
  pericope_ddl.add_column('ERM_MST_KRI_DEFINITION', 'OWNER_NAME', 'VARCHAR2(200)');
  pericope_ddl.add_column('ERM_MST_KRI_DEFINITION', 'DIRECTION',  q'[VARCHAR2(20) DEFAULT 'HIGHER_WORSE']');
  pericope_ddl.add_constraint('ERM_MST_KRI_DEFINITION', 'CHK_KRI_DIRECTION', q'[CHECK (DIRECTION IN ('HIGHER_WORSE', 'LOWER_WORSE'))]');

  -- Indexes on join columns
  pericope_ddl.create_index('IX_PIR_CYCLE',       'PER_TRN_IDENTIFY_RISK',            'ASSESSMENT_CYCLE_UUID');
  pericope_ddl.create_index('IX_PIR_PARENT',      'PER_TRN_IDENTIFY_RISK',            'IDENTIFY_RISK_UUID');
  pericope_ddl.create_index('IX_PCI_RISK',        'PER_TRN_CONTROL_IMPLEMENTATION',   'IDENTIFY_RISK_UUID');
  pericope_ddl.create_index('IX_PCI_RISK2',       'PER_TRN_CONTROL_IMPLEMENTATION',   'RISK_UUID');
  pericope_ddl.create_index('IX_PRM_RISK',        'PER_TRN_RISK_MONITORING',          'IDENTIFY_RISK_UUID');
  pericope_ddl.create_index('IX_PRM_RISK2',       'PER_TRN_RISK_MONITORING',          'RISK_UUID');
  pericope_ddl.create_index('IX_PIRA_RISK',       'PER_TRN_INHERENT_RISK_ASSESSMENT', 'IDENTIFY_RISK_UUID');
  pericope_ddl.create_index('IX_PIC_ASSESSMENT',  'PER_TRN_IMPACT_CATEGORY',          'INHERENT_RISK_ASSESSMENT_UUID');
  pericope_ddl.create_index('IX_PMP_PARENT',      'PER_TRN_MITIGATION_PLANS',         'PARENT_PLAN_UUID');
  pericope_ddl.create_index('IX_KRIR_KRI_DATE',   'ERM_TRN_KRI_READINGS',             'KRI_UUID, READING_DATE');
  pericope_ddl.create_index('IX_KPIA_KPI_DATE',   'ERM_TRN_KPI_ACTUALS',              'KPI_UUID, PERIOD_DATE');

  -- Referential integrity (each table's primary key column is UUID, as the API sees it)
  pericope_ddl.add_fk('PER_TRN_IDENTIFY_RISK',            'FK_PIR_CYCLE',  'ASSESSMENT_CYCLE_UUID', 'ERM_TRN_ASSESSMENT_CYCLE', 'UUID', 'SET NULL');
  pericope_ddl.add_fk('PER_TRN_IDENTIFY_RISK',            'FK_PIR_PARENT', 'IDENTIFY_RISK_UUID',    'PER_TRN_IDENTIFY_RISK',    'UUID', 'SET NULL');
  pericope_ddl.add_fk('PER_TRN_CONTROL_IMPLEMENTATION',   'FK_PCI_RISK',   'IDENTIFY_RISK_UUID',    'PER_TRN_IDENTIFY_RISK',    'UUID', 'CASCADE');
  pericope_ddl.add_fk('PER_TRN_RISK_MONITORING',          'FK_PRM_RISK',   'IDENTIFY_RISK_UUID',    'PER_TRN_IDENTIFY_RISK',    'UUID', 'CASCADE');
  pericope_ddl.add_fk('PER_TRN_INHERENT_RISK_ASSESSMENT', 'FK_PIRA_RISK',  'IDENTIFY_RISK_UUID',    'PER_TRN_IDENTIFY_RISK',    'UUID', 'CASCADE');
  pericope_ddl.add_fk('PER_TRN_MITIGATION_PLANS',         'FK_PMP_PARENT', 'PARENT_PLAN_UUID',      'PER_TRN_MITIGATION_PLANS', 'UUID', 'SET NULL');
  pericope_ddl.add_fk('ERM_TRN_KRI_READINGS',             'FK_KRIR_KRI',   'KRI_UUID',              'ERM_MST_KRI_DEFINITION',   'UUID', 'CASCADE');
  pericope_ddl.add_fk('ERM_TRN_KPI_ACTUALS',              'FK_KPIA_KPI',   'KPI_UUID',              'ERM_MST_KPI_DEFINITION',   'UUID', 'CASCADE');
END;
/

-- ############################################################################
-- STEP 05c: Migration V3
-- ############################################################################
PROMPT ===== Step 05c: Migration V3
-- =============================================================================
-- V3  Tables for the modules that used to live only in the browser
--
--   ERM_MST_CONTROL            control library
--   ERM_LNK_CONTROL_RISK       control  ↔ risk register links
--   ERM_MST_POLICY             policy register
--   ERM_LNK_POLICY_CONTROL     policy   ↔ control links
--   ERM_TRN_INCIDENT           incidents / loss events
--   ERM_LNK_INCIDENT_RISK      incident ↔ risk register links
--   ERM_MST_VENDOR             third-party (vendor) register
--   ERM_MST_BCP_PLAN           business continuity plans
--   ERM_MST_SCENARIO           stress / scenario analysis
--   ERM_MST_RISK_APPETITE      risk appetite statements
--   ERM_TRN_APPROVAL_REQUEST   maker-checker approval requests
--   ERM_TRN_APPROVAL_STEP      ordered approval steps of a request
--   ERM_MST_APP_SETTING        organisation settings (key → JSON)
--
-- KRIs reuse ERM_MST_KRI_DEFINITION / ERM_TRN_KRI_READINGS (extended in V2);
-- assessment cycles reuse ERM_TRN_ASSESSMENT_CYCLE.
--
-- Every table has a UUID identity key and CREATED_/UPDATED_ BY/ON columns that the
-- API fills in. All are REST-enabled with authentication required. Safe to re-run.
-- =============================================================================

BEGIN
  pericope_ddl.create_table('ERM_MST_CONTROL', q'[
    UUID                    NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY CONSTRAINT PK_EMC PRIMARY KEY,
    CONTROL_CODE            VARCHAR2(50)   NOT NULL CONSTRAINT UQ_EMC_CODE UNIQUE,
    CONTROL_NAME            VARCHAR2(200)  NOT NULL,
    DESCRIPTION             VARCHAR2(4000),
    CONTROL_TYPE            VARCHAR2(20)   CONSTRAINT CHK_EMC_TYPE CHECK (CONTROL_TYPE IN ('Preventive', 'Detective', 'Corrective', 'Compensating')),
    CONTROL_NATURE          VARCHAR2(20)   CONSTRAINT CHK_EMC_NATURE CHECK (CONTROL_NATURE IN ('Manual', 'Automated', 'Hybrid')),
    FREQUENCY               VARCHAR2(20)   CONSTRAINT CHK_EMC_FREQ CHECK (FREQUENCY IN ('Continuous', 'Daily', 'Weekly', 'Monthly', 'Quarterly', 'Annual', 'Event-driven')),
    OWNER_NAME              VARCHAR2(200),
    FRAMEWORKS              VARCHAR2(1000),
    DESIGN_EFFECTIVENESS    NUMBER(1)      CONSTRAINT CHK_EMC_DE CHECK (DESIGN_EFFECTIVENESS BETWEEN 1 AND 5),
    OPERATING_EFFECTIVENESS NUMBER(1)      CONSTRAINT CHK_EMC_OE CHECK (OPERATING_EFFECTIVENESS BETWEEN 1 AND 5),
    LAST_TESTED_ON          DATE,
    STATUS                  VARCHAR2(20)   DEFAULT 'Active' NOT NULL CONSTRAINT CHK_EMC_STATUS CHECK (STATUS IN ('Draft', 'Active', 'Retired')),
    CREATED_BY VARCHAR2(254), CREATED_ON TIMESTAMP DEFAULT SYSTIMESTAMP, UPDATED_BY VARCHAR2(254), UPDATED_ON TIMESTAMP]');

  pericope_ddl.create_table('ERM_LNK_CONTROL_RISK', q'[
    UUID         NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY CONSTRAINT PK_ELCR PRIMARY KEY,
    CONTROL_UUID NUMBER NOT NULL CONSTRAINT FK_ELCR_CONTROL REFERENCES ERM_MST_CONTROL (UUID) ON DELETE CASCADE,
    RISK_UUID    NUMBER NOT NULL,
    CONSTRAINT UQ_ELCR UNIQUE (CONTROL_UUID, RISK_UUID),
    CREATED_BY VARCHAR2(254), CREATED_ON TIMESTAMP DEFAULT SYSTIMESTAMP]');

  pericope_ddl.create_table('ERM_MST_POLICY', q'[
    UUID              NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY CONSTRAINT PK_EMP PRIMARY KEY,
    POLICY_CODE       VARCHAR2(50)  NOT NULL CONSTRAINT UQ_EMP_CODE UNIQUE,
    TITLE             VARCHAR2(300) NOT NULL,
    CATEGORY          VARCHAR2(100),
    VERSION_LABEL     VARCHAR2(20),
    OWNER_NAME        VARCHAR2(200),
    EFFECTIVE_DATE    DATE,
    NEXT_REVIEW_DATE  DATE,
    ACKNOWLEDGED_PCT  NUMBER(5,2)   CONSTRAINT CHK_EMP_ACK CHECK (ACKNOWLEDGED_PCT BETWEEN 0 AND 100),
    STATUS            VARCHAR2(20)  DEFAULT 'Draft' NOT NULL CONSTRAINT CHK_EMP_STATUS CHECK (STATUS IN ('Draft', 'Active', 'Retired')),
    CONSTRAINT CHK_EMP_DATES CHECK (NEXT_REVIEW_DATE IS NULL OR EFFECTIVE_DATE IS NULL OR NEXT_REVIEW_DATE >= EFFECTIVE_DATE),
    CREATED_BY VARCHAR2(254), CREATED_ON TIMESTAMP DEFAULT SYSTIMESTAMP, UPDATED_BY VARCHAR2(254), UPDATED_ON TIMESTAMP]');

  pericope_ddl.create_table('ERM_LNK_POLICY_CONTROL', q'[
    UUID         NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY CONSTRAINT PK_ELPC PRIMARY KEY,
    POLICY_UUID  NUMBER NOT NULL CONSTRAINT FK_ELPC_POLICY  REFERENCES ERM_MST_POLICY (UUID) ON DELETE CASCADE,
    CONTROL_UUID NUMBER NOT NULL CONSTRAINT FK_ELPC_CONTROL REFERENCES ERM_MST_CONTROL (UUID) ON DELETE CASCADE,
    CONSTRAINT UQ_ELPC UNIQUE (POLICY_UUID, CONTROL_UUID),
    CREATED_BY VARCHAR2(254), CREATED_ON TIMESTAMP DEFAULT SYSTIMESTAMP]');

  pericope_ddl.create_table('ERM_TRN_INCIDENT', q'[
    UUID              NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY CONSTRAINT PK_ETI PRIMARY KEY,
    INCIDENT_REF      VARCHAR2(50)   CONSTRAINT UQ_ETI_REF UNIQUE,
    TITLE             VARCHAR2(300)  NOT NULL,
    DESCRIPTION       VARCHAR2(4000),
    SEVERITY          VARCHAR2(10)   NOT NULL CONSTRAINT CHK_ETI_SEV CHECK (SEVERITY IN ('Low', 'Medium', 'High', 'Critical')),
    STATUS            VARCHAR2(20)   DEFAULT 'Open' NOT NULL CONSTRAINT CHK_ETI_STATUS CHECK (STATUS IN ('Open', 'Investigating', 'Mitigated', 'Closed')),
    CATEGORY          VARCHAR2(100),
    REPORTED_BY       VARCHAR2(200),
    ASSIGNED_TO       VARCHAR2(200),
    OCCURRED_ON       DATE,
    REPORTED_ON       DATE           DEFAULT TRUNC(SYSDATE) NOT NULL,
    CLOSED_ON         DATE,
    ROOT_CAUSE        VARCHAR2(4000),
    CORRECTIVE_ACTION VARCHAR2(4000),
    LOSS_AMOUNT       NUMBER(18,2)   CONSTRAINT CHK_ETI_LOSS CHECK (LOSS_AMOUNT >= 0),
    CONSTRAINT CHK_ETI_CLOSED CHECK (CLOSED_ON IS NULL OR CLOSED_ON >= REPORTED_ON),
    CREATED_BY VARCHAR2(254), CREATED_ON TIMESTAMP DEFAULT SYSTIMESTAMP, UPDATED_BY VARCHAR2(254), UPDATED_ON TIMESTAMP]');

  pericope_ddl.create_table('ERM_LNK_INCIDENT_RISK', q'[
    UUID          NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY CONSTRAINT PK_ELIR PRIMARY KEY,
    INCIDENT_UUID NUMBER NOT NULL CONSTRAINT FK_ELIR_INCIDENT REFERENCES ERM_TRN_INCIDENT (UUID) ON DELETE CASCADE,
    RISK_UUID     NUMBER NOT NULL,
    CONSTRAINT UQ_ELIR UNIQUE (INCIDENT_UUID, RISK_UUID),
    CREATED_BY VARCHAR2(254), CREATED_ON TIMESTAMP DEFAULT SYSTIMESTAMP]');

  pericope_ddl.create_table('ERM_MST_VENDOR', q'[
    UUID               NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY CONSTRAINT PK_EMV PRIMARY KEY,
    VENDOR_NAME        VARCHAR2(200) NOT NULL CONSTRAINT UQ_EMV_NAME UNIQUE,
    CATEGORY           VARCHAR2(100),
    TIER               VARCHAR2(10)  NOT NULL CONSTRAINT CHK_EMV_TIER CHECK (TIER IN ('Critical', 'High', 'Medium', 'Low')),
    COUNTRY_CODE       VARCHAR2(2),
    CONTRACT_VALUE     NUMBER(18,2)  CONSTRAINT CHK_EMV_VALUE CHECK (CONTRACT_VALUE >= 0),
    RISK_SCORE         NUMBER(3)     CONSTRAINT CHK_EMV_SCORE CHECK (RISK_SCORE BETWEEN 1 AND 100),
    LAST_ASSESSMENT_ON DATE,
    NEXT_REVIEW_ON     DATE,
    CONTACT_EMAIL      VARCHAR2(254),
    OPEN_FINDINGS      NUMBER(5)     DEFAULT 0 CONSTRAINT CHK_EMV_FINDINGS CHECK (OPEN_FINDINGS >= 0),
    STATUS             VARCHAR2(20)  DEFAULT 'Active' NOT NULL CONSTRAINT CHK_EMV_STATUS CHECK (STATUS IN ('Onboarding', 'Active', 'Offboarding', 'Exited')),
    CREATED_BY VARCHAR2(254), CREATED_ON TIMESTAMP DEFAULT SYSTIMESTAMP, UPDATED_BY VARCHAR2(254), UPDATED_ON TIMESTAMP]');

  pericope_ddl.create_table('ERM_MST_BCP_PLAN', q'[
    UUID           NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY CONSTRAINT PK_EMB PRIMARY KEY,
    PLAN_NAME      VARCHAR2(200) NOT NULL,
    SCOPE          VARCHAR2(1000),
    RTO_HOURS      NUMBER(6,1)   NOT NULL CONSTRAINT CHK_EMB_RTO CHECK (RTO_HOURS > 0),
    RPO_HOURS      NUMBER(6,1)   NOT NULL CONSTRAINT CHK_EMB_RPO CHECK (RPO_HOURS >= 0),
    OWNER_NAME     VARCHAR2(200),
    LAST_TESTED_ON DATE,
    NEXT_TEST_ON   DATE,
    STATUS         VARCHAR2(20)  DEFAULT 'Draft' NOT NULL CONSTRAINT CHK_EMB_STATUS CHECK (STATUS IN ('Draft', 'Active', 'Retired')),
    CONSTRAINT CHK_EMB_RPO_RTO CHECK (RPO_HOURS <= RTO_HOURS),
    CREATED_BY VARCHAR2(254), CREATED_ON TIMESTAMP DEFAULT SYSTIMESTAMP, UPDATED_BY VARCHAR2(254), UPDATED_ON TIMESTAMP]');

  pericope_ddl.create_table('ERM_MST_SCENARIO', q'[
    UUID            NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY CONSTRAINT PK_EMS PRIMARY KEY,
    SCENARIO_NAME   VARCHAR2(200) NOT NULL,
    DESCRIPTION     VARCHAR2(4000),
    SCENARIO_TYPE   VARCHAR2(20)  CONSTRAINT CHK_EMS_TYPE CHECK (SCENARIO_TYPE IN ('Stress Test', 'What-if', 'Reverse Stress', 'Tail Risk')),
    CATEGORY        VARCHAR2(100),
    SHOCK_PCT       NUMBER(7,2),
    BASELINE_LOSS   NUMBER(18,2)  CONSTRAINT CHK_EMS_BASE CHECK (BASELINE_LOSS >= 0),
    STRESSED_LOSS   NUMBER(18,2)  CONSTRAINT CHK_EMS_STRESS CHECK (STRESSED_LOSS >= 0),
    PROBABILITY_PCT NUMBER(5,2)   CONSTRAINT CHK_EMS_PROB CHECK (PROBABILITY_PCT BETWEEN 0 AND 100),
    OWNER_NAME      VARCHAR2(200),
    LAST_RUN_ON     TIMESTAMP,
    CREATED_BY VARCHAR2(254), CREATED_ON TIMESTAMP DEFAULT SYSTIMESTAMP, UPDATED_BY VARCHAR2(254), UPDATED_ON TIMESTAMP]');

  pericope_ddl.create_table('ERM_MST_RISK_APPETITE', q'[
    UUID             NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY CONSTRAINT PK_EMRA PRIMARY KEY,
    CATEGORY         VARCHAR2(100) NOT NULL CONSTRAINT UQ_EMRA_CATEGORY UNIQUE,
    STATEMENT        VARCHAR2(4000) NOT NULL,
    POSTURE          VARCHAR2(20)  NOT NULL CONSTRAINT CHK_EMRA_POSTURE CHECK (POSTURE IN ('Averse', 'Cautious', 'Open', 'Hungry')),
    TOLERANCE_SCORE  NUMBER(2)     NOT NULL CONSTRAINT CHK_EMRA_TOL CHECK (TOLERANCE_SCORE BETWEEN 1 AND 25),
    APPROVED_BY      VARCHAR2(200),
    APPROVED_ON      DATE,
    REVIEW_FREQUENCY VARCHAR2(20)  CONSTRAINT CHK_EMRA_REVIEW CHECK (REVIEW_FREQUENCY IN ('Quarterly', 'Semi-annual', 'Annual')),
    CREATED_BY VARCHAR2(254), CREATED_ON TIMESTAMP DEFAULT SYSTIMESTAMP, UPDATED_BY VARCHAR2(254), UPDATED_ON TIMESTAMP]');

  pericope_ddl.create_table('ERM_TRN_APPROVAL_REQUEST', q'[
    UUID           NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY CONSTRAINT PK_ETAR PRIMARY KEY,
    TITLE          VARCHAR2(300) NOT NULL,
    REQUEST_TYPE   VARCHAR2(30)  NOT NULL CONSTRAINT CHK_ETAR_TYPE CHECK (REQUEST_TYPE IN ('Risk Assessment', 'Mitigation Plan', 'Control Change', 'Policy Update', 'Risk Acceptance')),
    BUSINESS_UNIT  VARCHAR2(100),
    AMOUNT         NUMBER(18,2)  CONSTRAINT CHK_ETAR_AMOUNT CHECK (AMOUNT >= 0),
    DETAILS        VARCHAR2(4000),
    STATUS         VARCHAR2(20)  DEFAULT 'Pending' NOT NULL CONSTRAINT CHK_ETAR_STATUS CHECK (STATUS IN ('Pending', 'In Review', 'Approved', 'Rejected', 'Withdrawn')),
    SUBMITTED_BY   VARCHAR2(254) NOT NULL,
    SUBMITTED_NAME VARCHAR2(200),
    SUBMITTED_ON   TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,
    CLOSED_ON      TIMESTAMP,
    CREATED_BY VARCHAR2(254), CREATED_ON TIMESTAMP DEFAULT SYSTIMESTAMP, UPDATED_BY VARCHAR2(254), UPDATED_ON TIMESTAMP]');

  pericope_ddl.create_table('ERM_TRN_APPROVAL_STEP', q'[
    UUID          NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY CONSTRAINT PK_ETAS PRIMARY KEY,
    REQUEST_UUID  NUMBER       NOT NULL CONSTRAINT FK_ETAS_REQUEST REFERENCES ERM_TRN_APPROVAL_REQUEST (UUID) ON DELETE CASCADE,
    STEP_NO       NUMBER(2)    NOT NULL,
    APPROVER_ROLE VARCHAR2(30) NOT NULL CONSTRAINT CHK_ETAS_ROLE CHECK (APPROVER_ROLE IN ('Risk Manager', 'Administrator')),
    DECISION      VARCHAR2(10) CONSTRAINT CHK_ETAS_DECISION CHECK (DECISION IN ('Approved', 'Rejected')),
    DECIDED_BY    VARCHAR2(254),
    DECIDED_NAME  VARCHAR2(200),
    DECIDED_ON    TIMESTAMP,
    COMMENTS      VARCHAR2(2000),
    CONSTRAINT UQ_ETAS_STEP UNIQUE (REQUEST_UUID, STEP_NO),
    CONSTRAINT CHK_ETAS_REJECT_COMMENT CHECK (DECISION IS NULL OR DECISION = 'Approved' OR COMMENTS IS NOT NULL),
    CREATED_BY VARCHAR2(254), CREATED_ON TIMESTAMP DEFAULT SYSTIMESTAMP, UPDATED_BY VARCHAR2(254), UPDATED_ON TIMESTAMP]');

  pericope_ddl.create_table('ERM_MST_APP_SETTING', q'[
    UUID          NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY CONSTRAINT PK_EMAS PRIMARY KEY,
    SETTING_KEY   VARCHAR2(100) NOT NULL CONSTRAINT UQ_EMAS_KEY UNIQUE,
    SETTING_VALUE VARCHAR2(4000) CONSTRAINT CHK_EMAS_JSON CHECK (SETTING_VALUE IS JSON),
    CREATED_BY VARCHAR2(254), CREATED_ON TIMESTAMP DEFAULT SYSTIMESTAMP, UPDATED_BY VARCHAR2(254), UPDATED_ON TIMESTAMP]');

  -- Join / filter indexes
  pericope_ddl.create_index('IX_ELCR_RISK',      'ERM_LNK_CONTROL_RISK',     'RISK_UUID');
  pericope_ddl.create_index('IX_ELPC_CONTROL',   'ERM_LNK_POLICY_CONTROL',   'CONTROL_UUID');
  pericope_ddl.create_index('IX_ELIR_RISK',      'ERM_LNK_INCIDENT_RISK',    'RISK_UUID');
  pericope_ddl.create_index('IX_ETI_STATUS',     'ERM_TRN_INCIDENT',         'STATUS, SEVERITY');
  pericope_ddl.create_index('IX_ETAR_STATUS',    'ERM_TRN_APPROVAL_REQUEST', 'STATUS');
  pericope_ddl.create_index('IX_ETAR_SUBMITTER', 'ERM_TRN_APPROVAL_REQUEST', 'SUBMITTED_BY');

  -- Links to the risk register (removed together with the risk)
  pericope_ddl.add_fk('ERM_LNK_CONTROL_RISK',  'FK_ELCR_RISK', 'RISK_UUID', 'PER_TRN_IDENTIFY_RISK', 'UUID', 'CASCADE');
  pericope_ddl.add_fk('ERM_LNK_INCIDENT_RISK', 'FK_ELIR_RISK', 'RISK_UUID', 'PER_TRN_IDENTIFY_RISK', 'UUID', 'CASCADE');

  -- REST endpoints (authentication required)
  FOR t IN (SELECT column_value AS name FROM TABLE(sys.odcivarchar2list(
              'ERM_MST_CONTROL', 'ERM_LNK_CONTROL_RISK', 'ERM_MST_POLICY', 'ERM_LNK_POLICY_CONTROL',
              'ERM_TRN_INCIDENT', 'ERM_LNK_INCIDENT_RISK', 'ERM_MST_VENDOR', 'ERM_MST_BCP_PLAN',
              'ERM_MST_SCENARIO', 'ERM_MST_RISK_APPETITE', 'ERM_TRN_APPROVAL_REQUEST',
              'ERM_TRN_APPROVAL_STEP', 'ERM_MST_APP_SETTING'))) LOOP
    pericope_ddl.enable_rest(t.name);
  END LOOP;
END;
/

-- ############################################################################
-- STEP 05d: Migration V4
-- ############################################################################
PROMPT ===== Step 05d: Migration V4
-- =============================================================================
-- V4  Correctly spelled names for two legacy tables
--
-- The original schema has PER_MST_CONTROL_CLASIFICATION and
-- PER_MST_RISK_COMPUATION_LOGIC. Renaming them would break the APEX app, so a view
-- with the correct spelling is created over whichever one exists (read-only,
-- REST-enabled with authentication). New code should use the correct names.
-- Columns keep their legacy names (e.g. IS_STAGE_COMPLTED) because the existing
-- APEX application reads them; the API maps them for clients.
-- =============================================================================

DECLARE
  PROCEDURE alias_view(p_correct VARCHAR2, p_legacy VARCHAR2) IS
  BEGIN
    IF pericope_ddl.table_exists(p_correct) THEN
      pericope_ddl.log_msg('INFO', p_correct || ' already exists');
    ELSIF pericope_ddl.table_exists(p_legacy) THEN
      EXECUTE IMMEDIATE 'CREATE VIEW ' || p_correct || ' AS SELECT * FROM ' || p_legacy || ' WITH READ ONLY';
      pericope_ddl.log_msg('INFO', 'created view ' || p_correct || ' over ' || p_legacy);
      pericope_ddl.enable_rest(p_correct, 'VIEW');
    ELSE
      pericope_ddl.log_msg('INFO', 'neither ' || p_correct || ' nor ' || p_legacy || ' exists');
    END IF;
  END;
BEGIN
  alias_view('PER_MST_CONTROL_CLASSIFICATION', 'PER_MST_CONTROL_CLASIFICATION');
  alias_view('PER_MST_RISK_COMPUTATION_LOGIC', 'PER_MST_RISK_COMPUATION_LOGIC');
END;
/

-- ############################################################################
-- STEP 05e: Migration V5
-- ############################################################################
PROMPT ===== Step 05e: Migration V5
-- =============================================================================
-- V5  Align an existing schema with what the web app writes
--
-- The same changes a fresh install makes in db/install/04_app_alignment.sql, for a schema
-- that was set up before it (run after V1–V4). Safe to re-run.
--
-- * PER_TRN_RISK_MONITORING: IDENTIFY_RISK_UUID and ASSESSMENT_REFERENCE_NUMBER_UUID (the app
--   links an action to its risk with them), indexed and keyed like V2 intended.
-- * PER_TRN_RISK_MONITORING.ROOT_CAUSE becomes text when it is a number with no data
--   (the action-plan form saves a sentence).
-- * PER_TRN_INHERENT_RISK_ASSESSMENT: CREATED_ON / CREATED_BY, stamped by the API, so the
--   assessment history shows when and by whom each assessment was saved.
-- * The risk register's approval-status check also allows IN_REVIEW and PENDING.
-- =============================================================================
DECLARE
  n NUMBER;
BEGIN
  pericope_ddl.add_column('PER_TRN_RISK_MONITORING', 'IDENTIFY_RISK_UUID', 'NUMBER');
  pericope_ddl.add_column('PER_TRN_RISK_MONITORING', 'ASSESSMENT_REFERENCE_NUMBER_UUID', 'NUMBER');
  pericope_ddl.create_index('IX_PRM_RISK', 'PER_TRN_RISK_MONITORING', 'IDENTIFY_RISK_UUID');
  pericope_ddl.add_fk('PER_TRN_RISK_MONITORING', 'FK_PRM_RISK', 'IDENTIFY_RISK_UUID', 'PER_TRN_IDENTIFY_RISK', 'UUID', 'CASCADE');

  SELECT COUNT(*) INTO n FROM user_tab_columns
   WHERE table_name = 'PER_TRN_RISK_MONITORING' AND column_name = 'ROOT_CAUSE' AND data_type = 'NUMBER';
  IF n > 0 THEN
    EXECUTE IMMEDIATE 'SELECT COUNT(*) FROM PER_TRN_RISK_MONITORING WHERE ROOT_CAUSE IS NOT NULL' INTO n;
    IF n = 0 THEN
      EXECUTE IMMEDIATE 'ALTER TABLE PER_TRN_RISK_MONITORING MODIFY (ROOT_CAUSE VARCHAR2(2000 CHAR))';
      pericope_ddl.log_msg('INFO', 'PER_TRN_RISK_MONITORING.ROOT_CAUSE is now text');
    ELSE
      pericope_ddl.log_msg('WARNING', 'PER_TRN_RISK_MONITORING.ROOT_CAUSE is a number and has data: '
        || 'the action-plan form cannot save a root cause until it is converted to VARCHAR2 by hand');
    END IF;
  END IF;

  pericope_ddl.add_column('PER_TRN_INHERENT_RISK_ASSESSMENT', 'CREATED_ON', 'DATE DEFAULT SYSDATE');
  pericope_ddl.add_column('PER_TRN_INHERENT_RISK_ASSESSMENT', 'CREATED_BY', 'VARCHAR2(255 CHAR)');

  SELECT COUNT(*) INTO n FROM user_constraints
   WHERE table_name = 'PER_TRN_IDENTIFY_RISK' AND constraint_name = 'CK_IDR_APPR_STATUS'
     AND search_condition_vc NOT LIKE '%IN_REVIEW%';
  IF n > 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE PER_TRN_IDENTIFY_RISK DROP CONSTRAINT CK_IDR_APPR_STATUS';
    pericope_ddl.add_constraint('PER_TRN_IDENTIFY_RISK', 'CK_IDR_APPR_STATUS',
      q'[CHECK (APPROVAL_STATUS IS NULL OR APPROVAL_STATUS IN ('DRAFT','SUBMITTED','IN_REVIEW','PENDING','APPROVED','REJECTED'))]');
  END IF;
END;
/

