INSERT INTO PER_TRN_RISK_MONITORING (UUID, ROOT_CAUSE, MONITORING_TITLE, MONITORING_GOAL, CONTROLS_UUID, MITIGATION_OWNER, ESTIMATED_START_DATE, ESTIMATED_END_DATE, ACTUAL_START_DATE, ACTUAL_END_DATE, IS_STAGE_COMPLTED, APPROVAL_STATUS, RISK_UUID, IDENTIFY_RISK_UUID, ASSESSMENT_REFERENCE_NUMBER_UUID, COMPLETION_PCT, CONTROL_IMPLEMENTATION_UUID, MONITORING_TYPE) VALUES (1, 'The ERP runs in one data centre with no standby.', 'Set up a standby ERP environment with automatic failover', 'Order processing resumes within 4 hours if the primary ERP fails.', (SELECT UUID FROM ERM_MST_CONTROL WHERE CONTROL_CODE = 'CTL-OPS-INC-03'), 'Marcus Lee', DATE '2026-07-15', DATE '2026-12-15', DATE '2026-07-15', NULL, 'N', 'APPROVED', 1, 1, 0, 60, 1, 'CONTROL_ENHANCEMENT');
INSERT INTO PER_TRN_RISK_MONITORING (UUID, ROOT_CAUSE, MONITORING_TITLE, MONITORING_GOAL, CONTROLS_UUID, MITIGATION_OWNER, ESTIMATED_START_DATE, ESTIMATED_END_DATE, ACTUAL_START_DATE, ACTUAL_END_DATE, IS_STAGE_COMPLTED, APPROVAL_STATUS, RISK_UUID, IDENTIFY_RISK_UUID, ASSESSMENT_REFERENCE_NUMBER_UUID, COMPLETION_PCT, CONTROL_IMPLEMENTATION_UUID, MONITORING_TYPE) VALUES (2, 'Restore never tested end to end.', 'Quarterly restore test of ERP backups', 'Prove a full ERP restore inside the 8-hour RTO.', (SELECT UUID FROM ERM_MST_CONTROL WHERE CONTROL_CODE = 'CTL-IT-AUTH-01'), 'Marcus Lee', DATE '2026-07-01', DATE '2026-09-30', DATE '2026-07-01', DATE '2026-09-30', 'Y', 'APPROVED', 2, 2, 0, 100, 3, 'PERIODIC_REVIEW');
INSERT INTO PER_TRN_RISK_MONITORING (UUID, ROOT_CAUSE, MONITORING_TITLE, MONITORING_GOAL, CONTROLS_UUID, MITIGATION_OWNER, ESTIMATED_START_DATE, ESTIMATED_END_DATE, ACTUAL_START_DATE, ACTUAL_END_DATE, IS_STAGE_COMPLTED, APPROVAL_STATUS, RISK_UUID, IDENTIFY_RISK_UUID, ASSESSMENT_REFERENCE_NUMBER_UUID, COMPLETION_PCT, CONTROL_IMPLEMENTATION_UUID, MONITORING_TYPE) VALUES (3, 'Three critical components rely on one supplier.', 'Qualify a second supplier for critical components', 'Two approved suppliers for every A-class component.', (SELECT UUID FROM ERM_MST_CONTROL WHERE CONTROL_CODE = 'CTL-VEN-DUE-06'), 'Kenji Watanabe', DATE '2026-10-05', DATE '2027-03-31', DATE '2026-10-05', NULL, 'N', 'DRAFT', 3, 3, 0, 20, 5, 'NEW_CONTROL_PROPOSAL');
INSERT INTO PER_TRN_RISK_MONITORING (UUID, ROOT_CAUSE, MONITORING_TITLE, MONITORING_GOAL, CONTROLS_UUID, MITIGATION_OWNER, ESTIMATED_START_DATE, ESTIMATED_END_DATE, ACTUAL_START_DATE, ACTUAL_END_DATE, IS_STAGE_COMPLTED, APPROVAL_STATUS, RISK_UUID, IDENTIFY_RISK_UUID, ASSESSMENT_REFERENCE_NUMBER_UUID, COMPLETION_PCT, CONTROL_IMPLEMENTATION_UUID, MONITORING_TYPE) VALUES (4, 'Invoices without a purchase order were paid manually.', 'Enforce three-way match before any supplier payment', 'No invoice paid without a matching purchase order and goods receipt.', (SELECT UUID FROM ERM_MST_CONTROL WHERE CONTROL_CODE = 'CTL-FIN-SOD-07'), 'Elena Petrova', DATE '2026-07-01', DATE '2026-09-30', DATE '2026-07-01', DATE '2026-09-30', 'Y', 'APPROVED', 4, 4, 0, 100, 6, 'CONTROL_ENHANCEMENT');
INSERT INTO PER_TRN_RISK_MONITORING (UUID, ROOT_CAUSE, MONITORING_TITLE, MONITORING_GOAL, CONTROLS_UUID, MITIGATION_OWNER, ESTIMATED_START_DATE, ESTIMATED_END_DATE, ACTUAL_START_DATE, ACTUAL_END_DATE, IS_STAGE_COMPLTED, APPROVAL_STATUS, RISK_UUID, IDENTIFY_RISK_UUID, ASSESSMENT_REFERENCE_NUMBER_UUID, COMPLETION_PCT, CONTROL_IMPLEMENTATION_UUID, MONITORING_TYPE) VALUES (5, 'Manual spreadsheet reconciliation.', 'Automate bank-to-ledger reconciliation in the ERP', 'Remove manual matching for 95% of entries.', (SELECT UUID FROM ERM_MST_CONTROL WHERE CONTROL_CODE = 'CTL-FIN-REC-02'), 'Elena Petrova', DATE '2026-04-15', DATE '2026-06-30', DATE '2026-04-15', DATE '2026-06-30', 'Y', 'APPROVED', 5, 5, 0, 100, 7, 'CONTROL_ENHANCEMENT');
INSERT INTO PER_TRN_RISK_MONITORING (UUID, ROOT_CAUSE, MONITORING_TITLE, MONITORING_GOAL, CONTROLS_UUID, MITIGATION_OWNER, ESTIMATED_START_DATE, ESTIMATED_END_DATE, ACTUAL_START_DATE, ACTUAL_END_DATE, IS_STAGE_COMPLTED, APPROVAL_STATUS, RISK_UUID, IDENTIFY_RISK_UUID, ASSESSMENT_REFERENCE_NUMBER_UUID, COMPLETION_PCT, CONTROL_IMPLEMENTATION_UUID, MONITORING_TYPE) VALUES (6, 'Two near misses on line 3 in Q2.', 'Monthly safety walk-throughs on every production line', 'Lost-time injury rate below 0.5 per 200,000 hours worked.', NULL, 'Tom Becker', DATE '2026-07-01', DATE '2026-12-31', DATE '2026-07-01', NULL, 'N', 'APPROVED', 9, 9, 0, 50, NULL, 'PERIODIC_REVIEW');
INSERT INTO PER_TRN_RISK_MONITORING (UUID, ROOT_CAUSE, MONITORING_TITLE, MONITORING_GOAL, CONTROLS_UUID, MITIGATION_OWNER, ESTIMATED_START_DATE, ESTIMATED_END_DATE, ACTUAL_START_DATE, ACTUAL_END_DATE, IS_STAGE_COMPLTED, APPROVAL_STATUS, RISK_UUID, IDENTIFY_RISK_UUID, ASSESSMENT_REFERENCE_NUMBER_UUID, COMPLETION_PCT, CONTROL_IMPLEMENTATION_UUID, MONITORING_TYPE) VALUES (7, 'Leavers kept ERP access for weeks after leaving.', 'Quarterly review of ERP user access', 'Access no longer needed is removed within 5 days of each review.', (SELECT UUID FROM ERM_MST_CONTROL WHERE CONTROL_CODE = 'CTL-IT-AUTH-01'), 'Marcus Lee', DATE '2026-08-01', DATE '2026-10-31', DATE '2026-08-01', NULL, 'N', 'APPROVED', 16, 16, 0, 80, 11, 'PERIODIC_REVIEW');
