  pericope_ddl.add_fk('PER_TRN_RISK_MONITORING',        'FK_PRM_CONTROL', 'CONTROLS_UUID', 'ERM_MST_CONTROL', 'UUID', 'SET NULL');
  pericope_ddl.create_index('IX_PCI_CONTROL', 'PER_TRN_CONTROL_IMPLEMENTATION', 'CONTROL_ID');
  pericope_ddl.create_index('IX_PRM_CONTROL', 'PER_TRN_RISK_MONITORING', 'CONTROLS_UUID');
