BEGIN
  FOR o IN (SELECT object_name, object_type FROM user_objects
             WHERE object_type IN ('TABLE', 'VIEW')
               AND object_name IN (
                 'ERM_ACTIONS', 'ERM_CONTROLS', 'ERM_INCIDENTS', 'ERM_LNK_CONTROL_RISK', 'ERM_LNK_INCIDENT_RISK',
                 'ERM_LNK_POLICY_CONTROL', 'ERM_MST_APP_SETTING', 'ERM_MST_BCP_PLAN', 'ERM_MST_CONTROL',
                 'ERM_MST_KPI_DEFINITION', 'ERM_MST_KRI_DEFINITION', 'ERM_MST_POLICY', 'ERM_MST_RISK_APPETITE',
                 'ERM_MST_SCENARIO', 'ERM_MST_VENDOR', 'ERM_RISKS', 'ERM_TRN_APPROVAL_REQUEST',
                 'ERM_TRN_APPROVAL_STEP', 'ERM_TRN_ASSESSMENT_CYCLE', 'ERM_TRN_AUDIT_LOG', 'ERM_TRN_INCIDENT',
                 'ERM_TRN_KPI_ACTUALS', 'ERM_TRN_KRI_READINGS', 'PER_MST_BUSINESS_PROCESS',
                 'PER_MST_BUSINESS_SUB_PROCESS', 'PER_MST_COMPUTATION_OUTPUT', 'PER_MST_CONTROL_CATEGORY',
                 'PER_MST_CONTROL_CLASIFICATION', 'PER_MST_CONTROL_CLASSIFICATION',
                 'PER_MST_CONTROL_DESIGN_EFFECTIVENESS', 'PER_MST_CONTROL_FREQUENCY', 'PER_MST_CONTROL_REGISTER',
                 'PER_MST_CONTROL_TYPE', 'PER_MST_CURRENCY_TYPE', 'PER_MST_DESIGNATION', 'PER_MST_IMPACT',
                 'PER_MST_IMPACT_CATEGORY', 'PER_MST_IMPACT_PARTIES', 'PER_MST_IMPACT_SUB_CATEGORY',
                 'PER_MST_LIKELIHOOD', 'PER_MST_ORG_HIERARCHY', 'PER_MST_ORG_LEVEL', 'PER_MST_RISK_CATEGORY',
                 'PER_MST_RISK_CAUSAL_FACTOR', 'PER_MST_RISK_COMPUATION_LOGIC', 'PER_MST_RISK_COMPUTATION_LOGIC',
                 'PER_MST_RISK_CYCLE', 'PER_MST_RISK_DATA_SOURCE', 'PER_MST_RISK_ROOT_CAUSE',
                 'PER_MST_RISK_STATEMENT', 'PER_MST_RISK_SUB_CATEGORY', 'PER_MST_RISK_TYPE', 'PER_MST_ROLES',
                 'PER_MST_USER_DETAILS', 'PER_MST_USER_ROLES_MAPPING', 'PER_TRN_CONTROL_IMPLEMENTATION',
